<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CashService;
use EventMenu\Services\ConfiguredOrderService;
use EventMenu\Services\OrderHistoryService;
use EventMenu\Services\PaymentService;
use EventMenu\Services\ProductionService;
use EventMenu\Services\StockReservationService;

Auth::requirePermission('orders.create');$tenantId=em_require_tenant();$cartKey='pos_cart_'.$tenantId;if(!isset($_SESSION[$cartKey])||!is_array($_SESSION[$cartKey]))$_SESSION[$cartKey]=[];$cart=&$_SESSION[$cartKey];$configured=new ConfiguredOrderService();
$legacy=false;foreach($cart as$v){if(!is_array($v)){$legacy=true;break;}}if($legacy){$old=$cart;$cart=[];foreach($old as$productId=>$qty){$productId=(int)$productId;$qty=(float)$qty;if($productId<1||$qty<=0)continue;$cart[hash('sha256',$productId.':')]=['product_id'=>$productId,'qty'=>$qty,'option_ids'=>[]];}}
$cashService=Auth::can('cash.manage')?new CashService():null;$cashSession=$cashService?->currentSession();
function pos_flatten_options(mixed$value):array{$out=[];$walk=function($v)use(&$out,&$walk){if(is_array($v)){foreach($v as$x)$walk($x);return;}$id=(int)$v;if($id>0)$out[]=$id;};$walk($value);$out=array_values(array_unique($out));sort($out);return$out;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='add'){
        try{$id=(int)($_POST['product_id']??0);$qty=max(1,min(99,(int)($_POST['qty']??1)));$optionIds=pos_flatten_options($_POST['option_ids']??[]);$resolved=$configured->resolveLine($pdo,$tenantId,['product_id'=>$id,'qty'=>$qty,'option_ids'=>$optionIds],false);$lineKey=hash('sha256',$id.':'.implode(',',$resolved['option_ids']));if(isset($cart[$lineKey]))$cart[$lineKey]['qty']=min(99,(float)$cart[$lineKey]['qty']+$qty);else$cart[$lineKey]=['product_id'=>$id,'qty'=>$qty,'option_ids'=>$resolved['option_ids']];em_go('pos');}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('pos');}
    }
    if($action==='remove'){unset($cart[(string)($_POST['line_key']??'')]);em_go('pos');}
    if($action==='clear'){$cart=[];em_go('pos');}
    if($action==='create'){
        if(!$cart)exit('Adicione itens ao pedido.');$channel=(string)($_POST['channel']??'counter');if(!in_array($channel,['counter','pickup','table','delivery'],true))exit('Canal inválido.');$tableId=(int)($_POST['table_id']??0);$name=trim((string)($_POST['customer_name']??''));$phone=trim((string)($_POST['customer_phone']??''));$address=trim((string)($_POST['delivery_address']??''));$notes=mb_substr(trim((string)($_POST['notes']??'')),0,1000);$settle=(string)($_POST['settle']??'later');if(!in_array($settle,['later','cash'],true))exit('Forma de recebimento inválida.');
        if($channel==='delivery'&&($name===''||$phone===''||$address===''))exit('Delivery exige nome, telefone e endereço.');if($settle==='cash'&&(!Auth::can('payments.manage')||!Auth::can('cash.manage')))exit('Seu perfil não pode receber pagamentos.');
        try{$result=Database::transaction(function(PDO$tx)use($tenantId,$cart,$channel,$tableId,$name,$phone,$address,$notes,$settle,$configured):array{
            $tabId=null;$validTableId=null;if($channel==='table'){$t=$tx->prepare(Database::portableSql($tx,'SELECT id,status FROM restaurant_tables WHERE id=? AND tenant_id=? FOR UPDATE'));$t->execute([$tableId,$tenantId]);$table=$t->fetch();if(!$table||$table['status']==='inactive')throw new RuntimeException('Mesa inválida.');$tab=$tx->prepare(Database::portableSql($tx,'SELECT id FROM tabs WHERE tenant_id=? AND table_id=? AND status="open" ORDER BY id DESC LIMIT 1 FOR UPDATE'));$tab->execute([$tenantId,$tableId]);$tabId=$tab->fetchColumn();if($tabId===false)throw new RuntimeException('Abra uma comanda para esta mesa antes de lançar o pedido.');$validTableId=$tableId;}
            $customerId=null;if($name!==''){$existing=null;if($phone!==''){$c=$tx->prepare('SELECT id FROM customers WHERE tenant_id=? AND phone=? ORDER BY id DESC LIMIT 1');$c->execute([$tenantId,$phone]);$existing=$c->fetchColumn();}if($existing!==false&&$existing!==null)$customerId=(int)$existing;else{$c=$tx->prepare('INSERT INTO customers (tenant_id,name,phone) VALUES (?,?,?)');$c->execute([$tenantId,$name,$phone?:null]);$customerId=(int)$tx->lastInsertId();}}
            $items=[];$total=0;foreach(array_values($cart)as$line){$resolved=$configured->resolveLine($tx,$tenantId,$line,true);$total+=(int)$resolved['total_cents'];$items[]=$resolved;}if($total<=0)throw new RuntimeException('Pedido sem valor válido.');
            $token=bin2hex(random_bytes(20));$o=$tx->prepare('INSERT INTO orders (public_token,tenant_id,customer_id,channel,status,payment_status,subtotal_cents,total_cents,table_id,tab_id,delivery_address,notes,created_by) VALUES (?,?,?,?,"confirmed","unpaid",?,?,?,?,?,?,?)');$o->execute([$token,$tenantId,$customerId,$channel,$total,$total,$validTableId,$tabId,$channel==='delivery'?$address:null,$notes?:null,Auth::id()]);$orderId=(int)$tx->lastInsertId();$i=$tx->prepare('INSERT INTO order_items (order_id,product_id,name_snapshot,unit_price_cents,quantity,total_cents) VALUES (?,?,?,?,?,?)');foreach($items as$item){$i->execute([$orderId,$item['product_id'],$item['name'],$item['unit_price_cents'],$item['quantity'],$item['total_cents']]);$configured->persistModifiers($tx,$tenantId,$orderId,(int)$tx->lastInsertId(),$item);}
            (new StockReservationService())->reserve($tx,$tenantId,$orderId,$items,null);(new ProductionService())->ensureOrderJobs($tx,$tenantId,$orderId,Auth::id());(new OrderHistoryService())->record($tx,$tenantId,$orderId,null,'confirmed','pos','Pedido criado no PDV. Origem: '.$channel.'.',Auth::id());Auth::audit('order.created_pos','order',(string)$orderId,['channel'=>$channel,'total_cents'=>$total,'configured_lines'=>count($items)]);
            if($settle==='cash'){$cash=new CashService();if(!$cash->currentSession())throw new RuntimeException('Abra seu turno de caixa antes de receber dinheiro.');$payments=new PaymentService();$payment=$payments->create($orderId,'manual','pos-cash:'.$tenantId.':'.$orderId.':'.bin2hex(random_bytes(8)));$payments->confirmVerified(['tenant_id'=>$tenantId,'order_id'=>$orderId,'provider'=>'manual','provider_payment_id'=>'CASH-POS-'.strtoupper(bin2hex(random_bytes(8))),'amount_cents'=>$total,'currency'=>'BRL','account_reference'=>'manual']);$cash->recordPaidPayment((int)$payment['id'],'cash');Auth::audit('payment.cash_pos','order',(string)$orderId);}
            return ['order_id'=>$orderId,'paid'=>$settle==='cash'];});$cart=[];$orderId=(int)$result['order_id'];em_flash('ok',$result['paid']?'Pedido #'.$orderId.' criado e recebido. Produção e QR foram gerados.':'Pedido #'.$orderId.' criado. Produção roteada por estação; confirme o pagamento antes da retirada por QR.');em_go('orders',['view'=>$orderId]);}catch(Throwable$e){em_flash('error',$e->getMessage());em_go('pos');}
    }
}
$p=$pdo->prepare('SELECT p.*,c.name category_name,EXISTS(SELECT 1 FROM product_recipes r WHERE r.tenant_id=p.tenant_id AND r.product_id=p.id) has_recipe FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.tenant_id=? AND p.active=1 ORDER BY c.sort_order,c.name,p.name');$p->execute([$tenantId]);$products=$p->fetchAll();$modifierCatalog=$configured->catalogModifiers($pdo,$tenantId,array_column($products,'id'));$tables=$pdo->prepare('SELECT rt.id,rt.name,t.id tab_id,t.label FROM restaurant_tables rt JOIN tabs t ON t.table_id=rt.id AND t.status="open" WHERE rt.tenant_id=? AND rt.status<>"inactive" ORDER BY rt.name');$tables->execute([$tenantId]);$tables=$tables->fetchAll();
$cartRows=[];$cartTotal=0;$invalid=[];foreach($cart as$lineKey=>$line){try{$r=$configured->resolveLine($pdo,$tenantId,$line,false);$mods=[];foreach($r['modifiers']as$m)$mods[]=$m['group_name'].': '.$m['name'];$cartTotal+=(int)$r['total_cents'];$cartRows[]=['line_key'=>$lineKey,'name'=>$r['name'],'qty'=>$r['quantity'],'line'=>$r['total_cents'],'mods'=>$mods];}catch(Throwable$e){$invalid[]=$lineKey;}}foreach($invalid as$key)unset($cart[$key]);if($invalid)em_flash('error','Um item configurado foi alterado no cadastro e saiu do carrinho. Adicione novamente.');
em_header('Caixa / PDV','pos');
?><style>.pos-channel-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.pos-channel{position:relative}.pos-channel input{position:absolute;opacity:0;pointer-events:none}.pos-channel span{display:block;border:1px solid var(--line);border-radius:14px;padding:12px;background:#0d141f;min-height:68px}.pos-channel b,.pos-channel small{display:block}.pos-channel small{color:var(--muted);margin-top:3px}.pos-channel input:checked+span{border-color:var(--accent);box-shadow:0 0 0 2px rgba(244,185,66,.12);background:rgba(244,185,66,.08)}.pos-modifiers{border-top:1px solid var(--line);margin-top:12px;padding-top:10px}.pos-modifiers summary{cursor:pointer;color:var(--accent);font-weight:800}.pos-mod-group{padding:10px 0;border-bottom:1px solid var(--line)}.pos-mod-title{display:flex;justify-content:space-between;gap:8px;font-size:12px}.pos-mod-option{display:flex;justify-content:space-between;gap:8px;padding:7px 0;font-size:12px}.pos-mod-option input{width:auto}.cart-mods{font-size:11px;color:var(--muted);line-height:1.45;margin-top:3px}@media(max-width:680px){.pos-channel-grid{grid-template-columns:1fr 1fr}}</style>
<?php if(Auth::can('cash.manage')&&!$cashSession):?><div class="alert error">Seu turno de caixa está fechado. Você pode criar pedidos para pagar depois, mas para receber dinheiro precisa <a href="<?= Security::e(app_url('?route=cash')) ?>">abrir o caixa</a>.</div><?php endif;?><div class="grid" style="grid-template-columns:minmax(0,2fr) minmax(300px,1fr)"><section><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))"><?php foreach($products as$p):$out=(int)$p['track_stock']&&!(int)$p['has_recipe']&&(float)$p['stock_qty']<=0;$mods=$modifierCatalog[(int)$p['id']]??[];?><article class="card"><span class="muted"><?= Security::e($p['category_name']??'Sem categoria') ?></span><h3><?= Security::e($p['name']) ?></h3><p><strong><?= em_money($p['price_cents']) ?></strong><?php if($mods):?><br><span class="muted">Possui personalização / adicionais</span><?php endif;?><?php if($p['track_stock']&&!(int)$p['has_recipe']):?><br><span class="muted">Disponível: <?= Security::e((string)$p['stock_qty']) ?></span><?php elseif((int)$p['has_recipe']):?><br><span class="muted">Estoque controlado pela ficha técnica</span><?php endif;?></p><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><?php if($mods):?><details class="pos-modifiers" open><summary>Personalizar item</summary><?php foreach($mods as$g):$min=max((int)$g['min_select'],(int)$g['required']?1:0);$max=max(1,(int)$g['max_select']);?><div class="pos-mod-group"><div class="pos-mod-title"><strong><?= Security::e($g['name']) ?><?= $min>0?' *':'' ?></strong><span class="muted"><?= $min>0?'mín '.$min:'opcional' ?> · máx <?= $max ?></span></div><?php foreach($g['options']as$o):?><label class="pos-mod-option"><span><input type="checkbox" name="option_ids[<?= (int)$g['id'] ?>][]" value="<?= (int)$o['id'] ?>"> <?= Security::e($o['name']) ?></span><strong><?= (int)$o['price_delta_cents']===0?'incluído':((int)$o['price_delta_cents']>0?'+ ':'- ').em_money(abs((int)$o['price_delta_cents'])) ?></strong></label><?php endforeach;?></div><?php endforeach;?></details><?php endif;?><div class="actions" style="margin-top:12px"><input type="number" name="qty" min="1" max="99" value="1" style="width:72px"<?= $out?' disabled':'' ?>><button class="primary"<?= $out?' disabled':'' ?>><?= $out?'Esgotado':($mods?'Adicionar configurado':'Adicionar') ?></button></div></form></article><?php endforeach;?></div></section><aside class="card"><div class="section-head"><h2>Pedido</h2><?php if($cart):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="clear"><button class="secondary">Limpar</button></form><?php endif;?></div><?php if(!$cartRows):?><p class="muted">Carrinho vazio.</p><?php else:?><?php foreach($cartRows as$i):?><div class="section-head"><span><?= Security::e((string)$i['qty']) ?>× <?= Security::e($i['name']) ?><?php if($i['mods']):?><div class="cart-mods"><?= Security::e(implode(' · ',$i['mods'])) ?></div><?php endif;?><br><strong><?= em_money($i['line']) ?></strong></span><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="line_key" value="<?= Security::e($i['line_key']) ?>"><button class="secondary">×</button></form></div><?php endforeach;?><hr style="border-color:var(--line)"><h2>Total <?= em_money($cartTotal) ?></h2><form method="post" class="form-grid" id="pos-order-form"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="create"><div class="span-2"><span class="field-title">Como este pedido será atendido?</span><div class="pos-channel-grid"><label class="pos-channel"><input type="radio" name="channel" value="counter" checked><span><b>Balcão / PDV</b><small>Gera QR para conferência.</small></span></label><label class="pos-channel"><input type="radio" name="channel" value="pickup"><span><b>Retirada</b><small>Cliente busca e apresenta o QR.</small></span></label><label class="pos-channel"><input type="radio" name="channel" value="table"><span><b>Mesa / comanda</b><small>Sem QR de retirada.</small></span></label><label class="pos-channel"><input type="radio" name="channel" value="delivery"><span><b>Delivery</b><small>QR do pedido + fluxo de entrega.</small></span></label></div></div><label class="span-2">Recebimento<select name="settle"><option value="later">Pagar depois</option><?php if(Auth::can('payments.manage')&&Auth::can('cash.manage')):?><option value="cash"<?= !$cashSession?' disabled':'' ?>>Dinheiro<?= !$cashSession?' — abra o caixa':'' ?></option><?php endif;?></select></label><label class="span-2" id="pos-table-field" hidden>Mesa / comanda<select name="table_id"><option value="0">Selecione a mesa</option><?php foreach($tables as$t):?><option value="<?= (int)$t['id'] ?>"><?= Security::e($t['name'].' · Comanda #'.$t['tab_id'].($t['label']?' · '.$t['label']:'')) ?></option><?php endforeach;?></select></label><label class="span-2">Cliente<input name="customer_name" placeholder="Opcional, exceto delivery"></label><label class="span-2">Telefone<input name="customer_phone"></label><label class="span-2" id="pos-address-field" hidden>Endereço delivery<textarea name="delivery_address"></textarea></label><label class="span-2">Observações<textarea name="notes"></textarea></label><button class="primary span-2">Finalizar pedido</button></form><?php endif;?></aside></div><script>const channels=document.querySelectorAll('input[name="channel"]'),tableField=document.getElementById('pos-table-field'),addressField=document.getElementById('pos-address-field');function syncPosChannel(){const value=document.querySelector('input[name="channel"]:checked')?.value||'counter';if(tableField)tableField.hidden=value!=='table';if(addressField)addressField.hidden=value!=='delivery'}channels.forEach(el=>el.addEventListener('change',syncPosChannel));syncPosChannel();document.querySelectorAll('.pos-mod-group').forEach(group=>{const checks=[...group.querySelectorAll('input[type="checkbox"]')],txt=group.querySelector('.muted')?.textContent||'',m=txt.match(/máx\s*(\d+)/),max=m?parseInt(m[1],10):99;checks.forEach(c=>c.addEventListener('change',()=>{if(checks.filter(x=>x.checked).length>max){c.checked=false;alert('Máximo de '+max+' escolha(s) neste grupo.')}}))});</script><?php em_footer();
